const raw = $input.first().json.data ?? $input.first().json;
const hops = typeof raw === 'string' ? JSON.parse(raw) : raw;
if (!Array.isArray(hops) || !hops.length) throw new Error('No hops parsed');

const EXPECTED = Number($('Doc variant').first().json.expected_count);
if (hops.length !== EXPECTED)
  throw new Error(`Expected ${EXPECTED} hops, got ${hops.length} — re-probe before ingesting`);

const SPECS = ['alpha','beta','cohumulone','total_oils','myrcene','humulene',
               'caryophyllene','farnesene'];

const num = v => (v === null || v === undefined || v === '') ? null : Number(v);

const rows = hops.map((h, i) => {
  const name = String(h.name ?? '').trim();
  if (!name) throw new Error(`Hop ${i} has no name`);
  if (name.length < 2) throw new Error(`Hop ${i} has a suspiciously short name "${name}" — `
    + `the column split probably cut a label in half`);

  const out = { name,
    origin: h.origin || null, hop_type: h.hop_type || null,
    description: h.description || null,
    beer_types: h.beer_types ?? [], flavour: h.flavour ?? [],
    alternatives: h.alternatives ?? [] };

  for (const k of SPECS) {
    const lo = num(h[`${k}_min`]), hi = num(h[`${k}_max`]);
    if (lo !== null && Number.isNaN(lo)) throw new Error(`${name}: ${k}_min is not numeric`);
    if (hi !== null && Number.isNaN(hi)) throw new Error(`${name}: ${k}_max is not numeric`);
    // ⛔ An inverted range means the decimal comma was misread — 14,5 parsed as
    // two numbers would land here. Refuse rather than store it.
    if (lo !== null && hi !== null && lo > hi)
      throw new Error(`${name}: ${k} range is inverted (${lo} > ${hi}) — check the decimal comma`);
    // A percentage above 100 is the other signature of the same misread.
    if (k !== 'total_oils' && hi !== null && hi > 100)
      throw new Error(`${name}: ${k}_max is ${hi}% — above 100, so the value was misparsed`);
    out[`${k}_min`] = lo; out[`${k}_max`] = hi;
  }
  return out;
});

const dup = rows.map(r => r.name).filter((v, i, a) => a.indexOf(v) !== i);
if (dup.length) throw new Error(`Duplicate hop name(s): ${[...new Set(dup)].join(', ')}`);

const filled = k => rows.filter(r => r[k] !== null && r[k] !== undefined
                                  && !(Array.isArray(r[k]) && !r[k].length)).length;
return [{ json: { rows, stats: {
  hops: rows.length, with_origin: filled('origin'), with_type: filled('hop_type'),
  with_alpha: rows.filter(r => r.alpha_min !== null || r.alpha_max !== null).length,
  with_flavour: filled('flavour'), with_alternatives: filled('alternatives'),
  open_bounds: rows.reduce((n, r) => n + SPECS.filter(k =>
    (r[`${k}_min`] === null) !== (r[`${k}_max`] === null)).length, 0),
} } }];

const items = $input.all();
return [{ json: {
  ids:    items.map(i => i.json.id),
  inputs: items.map(i => i.json.content),
}}];

const src = $('Assemble embed input').first().json;
const emb = $json.embeddings;
if (!Array.isArray(emb) || emb.length !== src.ids.length)
  throw new Error(`Embedding count ${emb?.length} != inputs ${src.ids.length}`);
if (emb[0].length !== 1024)
  throw new Error(`Expected 1024 dims, got ${emb[0].length} — schema mismatch`);
return src.ids.map((id, i) => ({
  json: { chunk_id: id, embedding: '[' + emb[i].join(',') + ']' },
}));

const r = $json;
if (r.missing > 0) throw new Error(`${r.missing} of ${r.total} cards have no embedding — not promoted`);
if (!r.is_current) throw new Error(`Version ${r.version_id} did not become current`);
return [{ json: r }];
